  fd_blake3_crc_be_chain( msg, sz, fd_blake3_crc_root_nb( sz ), root->cv );
  memset( root->block, 0, 64UL );
  if( sz ) memcpy( root->block, msg + fd_blake3_crc_root_off( sz ), fd_blake3_crc_root_kbytes( sz ) );
  root->blen  = (uint)fd_blake3_crc_root_kbytes( sz );
  root->flags = 10U | ( sz<=64U ? 1U : 0U );
