/* fd_blake3_init starts a calculation on the joined state sha, discarding any calculation in
   progress; returns sha. */
fd_blake3_t *
fd_blake3_init( fd_blake3_t * sha ) {
  sha->pos      = (fd_blake3_pos_t){ .magic = FD_BLAKE3_MAGIC };
  sha->block_sz = 0UL;
  return sha;
}

